import React, { useState, useEffect } from 'react';
import { 
  Calendar, 
  Badge, 
  Modal, 
  Form, 
  Input, 
  DatePicker, 
  TimePicker, 
  Select, 
  Button, 
  Space, 
  Tag, 
  Tooltip,
  message,
  Popover,
  List,
  Divider
} from 'antd';
import { 
  PlusOutlined, 
  EditOutlined, 
  DeleteOutlined, 
  ClockCircleOutlined,
  CalendarOutlined,
  ReloadOutlined,
  ExclamationCircleOutlined
} from '@ant-design/icons';
import type { Dayjs } from 'dayjs';
import dayjs from 'dayjs';
import 'dayjs/locale/ru';
import { usePermissions } from '../hooks/usePermissions';

dayjs.locale('ru');

const { TextArea } = Input;

// Типы данных
interface Reminder {
  id: number;
  title: string;
  description: string;
  reminder_date: string;
  reminder_type: string;
  priority: string;
  is_sent: boolean;
  is_recurring: boolean;
  recurrence_pattern?: string | null;
  created_at: string;
}

interface CalendarGridProps {
  reminders: Reminder[];
  onReminderCreate: (reminder: Omit<Reminder, 'id' | 'created_at' | 'is_sent'>) => Promise<void>;
  onReminderUpdate: (id: number, reminder: Partial<Reminder>) => Promise<void>;
  onReminderDelete: (id: number) => Promise<void>;
  loading?: boolean;
}

// Цвета для приоритетов
const priorityColors = {
  low: '#52c41a',      // зеленый
  medium: '#1890ff',   // синий
  high: '#fa8c16',     // оранжевый
  urgent: '#f5222d'    // красный
};

// Цвета для типов
const typeColors = {
  birthday: '#eb2f96',    // розовый
  meeting: '#1890ff',     // синий
  deadline: '#f5222d',    // красный
  holiday: '#52c41a',     // зеленый
  custom: '#722ed1',      // фиолетовый
  reminder: '#13c2c2'     // циан
};

const CalendarGrid: React.FC<CalendarGridProps> = ({
  reminders,
  onReminderCreate,
  onReminderUpdate,
  onReminderDelete,
  loading = false
}) => {
  const [selectedDate, setSelectedDate] = useState<Dayjs>(dayjs());
  const [modalVisible, setModalVisible] = useState(false);
  const [editingReminder, setEditingReminder] = useState<Reminder | null>(null);
  const [form] = Form.useForm();
  const { hasPermission } = usePermissions();

  // Права доступа
  const canCreate = hasPermission('api.reminders.write');
  const canEdit = hasPermission('api.reminders.write');
  const canDelete = hasPermission('api.reminders.delete');

  // Получение напоминаний для конкретной даты
  const getRemindersForDate = (date: Dayjs): Reminder[] => {
    return reminders.filter(reminder => 
      dayjs(reminder.reminder_date).format('YYYY-MM-DD') === date.format('YYYY-MM-DD')
    );
  };

  // Рендер ячейки календаря
  const dateCellRender = (date: Dayjs) => {
    const dayReminders = getRemindersForDate(date);
    
    if (dayReminders.length === 0) return null;

    return (
      <div className="calendar-events">
        {dayReminders.slice(0, 3).map((reminder, index) => (
          <Badge
            key={reminder.id}
            status="processing"
            color={priorityColors[reminder.priority as keyof typeof priorityColors]}
            text={
              <Tooltip title={`${reminder.title} (${reminder.priority})`}>
                <span className="calendar-event-text">
                  {reminder.title.length > 10 ? `${reminder.title.slice(0, 10)}...` : reminder.title}
                </span>
              </Tooltip>
            }
            style={{ 
              display: 'block', 
              fontSize: '11px',
              marginBottom: '2px',
              whiteSpace: 'nowrap',
              overflow: 'hidden'
            }}
          />
        ))}
        {dayReminders.length > 3 && (
          <Text type="secondary" style={{ fontSize: '10px' }}>
            +{dayReminders.length - 3} еще
          </Text>
        )}
      </div>
    );
  };

  // Обработка выбора даты
  const onDateSelect = (date: Dayjs) => {
    setSelectedDate(date);
    const dayReminders = getRemindersForDate(date);
    
    if (dayReminders.length > 0) {
      // Показываем попап с напоминаниями на эту дату
      Modal.info({
        title: `Напоминания на ${date.format('DD MMMM YYYY')}`,
        width: 600,
        content: (
          <List
            dataSource={dayReminders}
            renderItem={(reminder) => (
              <List.Item
                actions={[
                  canEdit && (
                    <Button 
                      type="text" 
                      icon={<EditOutlined />} 
                      onClick={() => handleEdit(reminder)}
                    />
                  ),
                  canDelete && (
                    <Button 
                      type="text" 
                      danger 
                      icon={<DeleteOutlined />} 
                      onClick={() => handleDelete(reminder.id)}
                    />
                  )
                ].filter(Boolean)}
              >
                <List.Item.Meta
                  title={
                    <Space>
                      <Text strong>{reminder.title}</Text>
                      <Tag color={typeColors[reminder.reminder_type as keyof typeof typeColors]}>
                        {reminder.reminder_type}
                      </Tag>
                      <Tag color={priorityColors[reminder.priority as keyof typeof priorityColors]}>
                        {reminder.priority}
                      </Tag>
                      {reminder.is_recurring && <ReloadOutlined />}
                    </Space>
                  }
                  description={
                    <Space direction="vertical" size="small">
                      <Text>{reminder.description}</Text>
                      <Text type="secondary">
                        <ClockCircleOutlined /> {dayjs(reminder.reminder_date).format('HH:mm')}
                      </Text>
                    </Space>
                  }
                />
              </List.Item>
            )}
          />
        )
      });
    }
  };

  // Открытие модала создания
  const handleCreate = (date?: Dayjs) => {
    setEditingReminder(null);
    form.resetFields();
    
    const now = dayjs();
    const baseDate = date || selectedDate || now;
    // Если создаём на сегодня и время по умолчанию уже прошло, смещаем на +15 мин
    const defaultTime = baseDate.isSame(now, 'day')
      ? now.add(15, 'minute')
      : baseDate.hour(9).minute(0);
    form.setFieldsValue({
      reminder_date: baseDate,
      reminder_time: defaultTime
    });
    
    setModalVisible(true);
  };

  // Открытие модала редактирования
  const handleEdit = (reminder: Reminder) => {
    setEditingReminder(reminder);
    const reminderDate = dayjs(reminder.reminder_date);
    
    form.setFieldsValue({
      title: reminder.title,
      description: reminder.description,
      reminder_date: reminderDate,
      reminder_time: reminderDate,
      reminder_type: reminder.reminder_type,
      priority: reminder.priority,
      is_recurring: reminder.is_recurring,
      recurrence_pattern: reminder.recurrence_pattern
    });
    
    setModalVisible(true);
  };

  // Удаление напоминания
  const handleDelete = async (id: number) => {
    Modal.confirm({
      title: 'Удалить напоминание?',
      icon: <ExclamationCircleOutlined />,
      content: 'Это действие нельзя отменить.',
      okText: 'Удалить',
      okType: 'danger',
      cancelText: 'Отмена',
      onOk: async () => {
        try {
          await onReminderDelete(id);
          message.success('Напоминание удалено');
        } catch (error) {
          message.error('Ошибка удаления напоминания');
        }
      }
    });
  };

  // Сохранение напоминания
  const handleSave = async () => {
    try {
      const values = await form.validateFields();
      
      // Объединяем дату и время
      const reminderDateTime = values.reminder_date
        .hour(values.reminder_time.hour())
        .minute(values.reminder_time.minute());
      // Гарантируем, что напоминание в будущем (минимум +1 мин)
      const minFuture = dayjs().add(1, 'minute');
      const finalDt = reminderDateTime.isBefore(minFuture) ? minFuture : reminderDateTime;

      const reminderData = {
        title: values.title,
        description: values.description || values.title,
        reminder_date: finalDt.toISOString(),
        reminder_type: values.reminder_type,
        priority: values.priority,
        is_recurring: values.is_recurring || false,
        recurrence_pattern: values.is_recurring ? values.recurrence_pattern : null
      };

      if (editingReminder) {
        await onReminderUpdate(editingReminder.id, reminderData);
        message.success('Напоминание обновлено');
      } else {
        await onReminderCreate(reminderData);
        message.success('Напоминание создано');
      }

      setModalVisible(false);
      form.resetFields();
    } catch (error: any) {
      const msg = String(error?.message || 'Ошибка сохранения напоминания');
      message.error(msg);
    }
  };

  return (
    <div className="calendar-grid-container">
      <div className="calendar-header" style={{ marginBottom: 12, display:'flex', gap:12, alignItems:'center' }}>
        {canCreate && (
          <Button 
            type="primary" 
            icon={<PlusOutlined />}
            onClick={() => handleCreate(selectedDate)}
            loading={loading}
          >
            Создать напоминание
          </Button>
        )}
      </div>

      <Calendar
        dateCellRender={dateCellRender}
        onSelect={onDateSelect}
        value={selectedDate}
        onChange={setSelectedDate}
      />

      {/* Модал создания/редактирования */}
      <Modal
        title={editingReminder ? 'Редактировать напоминание' : 'Создать напоминание'}
        open={modalVisible}
        onOk={handleSave}
        onCancel={() => {
          setModalVisible(false);
          form.resetFields();
        }}
        okText="Сохранить"
        cancelText="Отмена"
        confirmLoading={loading}
        width={600}
      >
        <Form
          form={form}
          layout="vertical"
          initialValues={{
            reminder_type: 'custom',
            priority: 'medium',
            is_recurring: false
          }}
        >
          <Form.Item
            name="title"
            label="Название"
            rules={[{ required: true, message: 'Введите название напоминания' }]}
          >
            <Input placeholder="Название напоминания" />
          </Form.Item>

          <Form.Item
            name="description"
            label="Описание"
          >
            <TextArea 
              placeholder="Подробное описание (необязательно)"
              rows={3}
            />
          </Form.Item>

          <Space.Compact style={{ width: '100%' }}>
            <Form.Item
              name="reminder_date"
              label="Дата"
              rules={[{ required: true, message: 'Выберите дату' }]}
              style={{ flex: 1, marginRight: 8 }}
            >
              <DatePicker 
                style={{ width: '100%' }}
                format="DD.MM.YYYY"
                placeholder="Выберите дату"
              />
            </Form.Item>

            <Form.Item
              name="reminder_time"
              label="Время"
              rules={[{ required: true, message: 'Выберите время' }]}
              style={{ flex: 1 }}
            >
              <TimePicker 
                style={{ width: '100%' }}
                format="HH:mm"
                placeholder="Выберите время"
              />
            </Form.Item>
          </Space.Compact>

          <Space.Compact style={{ width: '100%' }}>
            <Form.Item
              name="reminder_type"
              label="Тип"
              style={{ flex: 1, marginRight: 8 }}
            >
              <Select>
                <Select.Option value="custom">Обычное</Select.Option>
                <Select.Option value="meeting">Встреча</Select.Option>
                <Select.Option value="deadline">Дедлайн</Select.Option>
                <Select.Option value="birthday">День рождения</Select.Option>
                <Select.Option value="holiday">Праздник</Select.Option>
                <Select.Option value="reminder">Напоминание</Select.Option>
              </Select>
            </Form.Item>

            <Form.Item
              name="priority"
              label="Приоритет"
              style={{ flex: 1 }}
            >
              <Select>
                <Select.Option value="low">Низкий</Select.Option>
                <Select.Option value="medium">Средний</Select.Option>
                <Select.Option value="high">Высокий</Select.Option>
                <Select.Option value="urgent">Срочный</Select.Option>
              </Select>
            </Form.Item>
          </Space.Compact>

          <Form.Item
            name="is_recurring"
            valuePropName="checked"
          >
            <Space>
              <input type="checkbox" />
              <span>Повторяющееся напоминание</span>
            </Space>
          </Form.Item>

          <Form.Item
            noStyle
            shouldUpdate={(prevValues, currentValues) => 
              prevValues.is_recurring !== currentValues.is_recurring
            }
          >
            {({ getFieldValue }) =>
              getFieldValue('is_recurring') ? (
                <Form.Item
                  name="recurrence_pattern"
                  label="Повтор"
                  rules={[{ required: true, message: 'Выберите частоту повтора' }]}
                >
                  <Select placeholder="Выберите частоту">
                    <Select.Option value="daily">Ежедневно</Select.Option>
                    <Select.Option value="weekly">Еженедельно</Select.Option>
                    <Select.Option value="monthly">Ежемесячно</Select.Option>
                    <Select.Option value="yearly">Ежегодно</Select.Option>
                  </Select>
                </Form.Item>
              ) : null
            }
          </Form.Item>
        </Form>
      </Modal>

      <style jsx>{`
        .calendar-grid-container { width: 100%; }
        .calendar-events {
          max-height: 60px;
          overflow: hidden;
        }
        
        .calendar-event-text {
          font-size: 11px;
          line-height: 1.2;
        }
        
        .ant-picker-calendar-date-content {
          height: 60px !important;
          overflow: hidden;
        }
        
        .ant-badge-status-text {
          font-size: 11px !important;
        }
      `}</style>
    </div>
  );
};

export default CalendarGrid;
