import React, { useEffect, useState } from 'react';
import { 
  Card, 
  Tabs, 
  List, 
  Tag, 
  Space, 
  Button, 
  Typography, 
  Statistic, 
  Row, 
  Col,
  Alert,
  Spin,
  Empty,
  Badge
} from 'antd';
import { 
  CalendarOutlined, 
  ClockCircleOutlined, 
  BellOutlined,
  CheckCircleOutlined,
  ExclamationCircleOutlined,
  InfoCircleOutlined,
  BarChartOutlined
} from '@ant-design/icons';
import CalendarGrid from '../components/CalendarGrid';
import { api, getTelegramUser } from '../api';
import { usePermissions } from '../hooks/usePermissions';
import dayjs from 'dayjs';
import 'dayjs/locale/ru';

dayjs.locale('ru');

const { Title, Text } = Typography;
const { TabPane } = Tabs;

// Типы данных
interface DateEvent {
  message_id: string;
  text_preview: string;
  created_at: string;
  normalized_date: string | null;
  keyword: string;
}

interface Reminder {
  id: number;
  title: string;
  description: string;
  reminder_date: string;
  reminder_type: string;
  priority: string;
  is_sent: boolean;
  is_recurring: boolean;
  recurrence_pattern?: string | null;
  created_at: string;
}

// Calm‑палитра тегов (стили вместо предустановленных цветов AntD)
const getTypeClass = (type: string) => `sp-tag sp-tag--type-${type}`;
const getPrioClass = (p: string) => `sp-tag sp-tag--prio-${p}`;

const DatesRemindersV2: React.FC = () => {
  const [events, setEvents] = useState<DateEvent[]>([]);
  const [reminders, setReminders] = useState<Reminder[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState('calendar');

  const telegramUser = getTelegramUser();
  const { hasPermission, hasRole, state: permsState, refreshPermissions } = usePermissions();
  const isArchitect = hasRole('architect');
  const [overrideTgId, setOverrideTgId] = useState<string>('');

  const requireTgId = (): string => {
    const id = (isArchitect && overrideTgId) ? overrideTgId : telegramUser?.id?.toString();
    if (!id) {
      throw new Error('Не найден Telegram ID. Откройте приложение из Telegram.');
    }
    return id;
  };

  // Загрузка событий из сообщений
  const loadEvents = async () => {
    setLoading(true);
    setError(null);
    try {
      const resp = await api('/messages/dates', {
        method: 'GET',
        headers: {
          'X-Telegram-User-ID': requireTgId(),
        }
      });
      if (resp.status === 'success') {
        setEvents(resp.events || []);
      }
    } catch (e: any) {
      setError(e?.message || 'Ошибка загрузки дат');
    } finally {
      setLoading(false);
    }
  };

  // Загрузка напоминаний
  const loadReminders = async () => {
    setLoading(true);
    try {
      const resp = await api('/reminders?include_sent=true&limit=200', { 
        method: 'GET',
        headers: {
          'X-Telegram-User-ID': requireTgId(),
        }
      });
      const arr = Array.isArray(resp) ? resp : [];
      // Сортируем по дате напоминания (ближайшие сверху)
      arr.sort((a:any,b:any)=> new Date(a.reminder_date).getTime() - new Date(b.reminder_date).getTime());
      setReminders(arr);
    } catch (e: any) {
      console.error('Ошибка загрузки напоминаний:', e);
      setError(e?.message || 'Ошибка загрузки напоминаний');
    } finally {
      setLoading(false);
    }
  };

  // Создание напоминания
  const handleReminderCreate = async (reminderData: Omit<Reminder, 'id' | 'created_at' | 'is_sent'>) => {
    const payload = {
      ...reminderData,
      ai_prompt: `Напоминание: ${reminderData.title}`
    };

    const created = await api('/reminders', {
      method: 'POST',
      headers: { 
        'Content-Type': 'application/json',
        'X-Telegram-User-ID': requireTgId(),
      },
      body: JSON.stringify(payload),
    });

    if (created && created.id) {
      // Мгновенно добавляем в список, затем делаем принудительный рефреш
      try { setReminders(prev => [created as any, ...prev]); } catch {}
      try { setTimeout(() => { void loadReminders(); }, 600); } catch {}
    }
  };

  // Обновление напоминания
  const handleReminderUpdate = async (id: number, reminderData: Partial<Reminder>) => {
    const updated = await api(`/reminders/${id}`, {
      method: 'PUT',
      headers: { 
        'Content-Type': 'application/json',
        'X-Telegram-User-ID': requireTgId(),
      },
      body: JSON.stringify(reminderData),
    });

    if (updated) {
      setReminders(reminders.map(r => r.id === id ? { ...r, ...updated } : r));
    }
  };

  // Удаление напоминания
  const handleReminderDelete = async (id: number) => {
    await api(`/reminders/${id}`, { 
      method: 'DELETE',
      headers: {
        'X-Telegram-User-ID': requireTgId(),
      }
    });
    setReminders(reminders.filter(r => r.id !== id));
  };

  // Статистика напоминаний
  const getStatistics = () => {
    const total = reminders.length;
    const pending = reminders.filter(r => !r.is_sent && dayjs(r.reminder_date).isAfter(dayjs())).length;
    const overdue = reminders.filter(r => !r.is_sent && dayjs(r.reminder_date).isBefore(dayjs())).length;
    const completed = reminders.filter(r => r.is_sent).length;
    const recurring = reminders.filter(r => r.is_recurring).length;

    return { total, pending, overdue, completed, recurring };
  };

  const stats = getStatistics();

  // Группировка напоминаний по статусу
  const getGroupedReminders = () => {
    const now = dayjs();
    
    return {
      overdue: reminders.filter(r => !r.is_sent && dayjs(r.reminder_date).isBefore(now)),
      today: reminders.filter(r => !r.is_sent && dayjs(r.reminder_date).format('YYYY-MM-DD') === now.format('YYYY-MM-DD')),
      upcoming: reminders.filter(r => !r.is_sent && dayjs(r.reminder_date).isAfter(now) && !dayjs(r.reminder_date).isSame(now, 'day')),
      completed: reminders.filter(r => r.is_sent)
    };
  };

  const groupedReminders = getGroupedReminders();

  useEffect(() => {
    loadEvents();
    loadReminders();
  }, []);

  // Разрешаем доступ Архитектору даже без явного permission-флага
  if (!hasPermission('api.reminders.read') && !hasRole('architect')) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-50 to-purple-50 p-4">
        <Card>
          <Alert
            message="Доступ ограничен"
            description="У вас нет прав для просмотра календаря и напоминаний."
            type="warning"
            showIcon
          />
        </Card>
      </div>
    );
  }

  return (
    <div className="min-h-screen p-4" style={{ background: 'var(--sp-gradient-background)', overflowX: 'hidden' }}>
      <div className="max-w-7xl mx-auto space-y-6">
        {/* Заголовок */}
        <Card className="sp-edge-highlight sp-card-elevated">
          <div className="flex justify-between items-center">
            <div>
              <Title level={2} style={{ margin: 0 }}>
                <CalendarOutlined /> Календарь и напоминания
              </Title>
              <Text type="secondary">
                Управление напоминаниями и просмотр важных дат из сообщений
              </Text>
            </div>
            <Space>
              <Button onClick={() => { try { refreshPermissions(); } catch {} }}>Обновить роли</Button>
            </Space>
          </div>
          <div style={{marginTop:8}}>
            <Text type="secondary">Текущие роли: {(permsState.roles||[]).map(r=>r.name).join(', ') || '—'}</Text>
          </div>
          {isArchitect && (
            <div style={{marginTop:8}}>
              <Space>
                <Text type="secondary">TG ID пользователя:</Text>
                <input
                  value={overrideTgId}
                  onChange={(e)=>setOverrideTgId(e.target.value.replace(/[^0-9]/g,''))}
                  placeholder="468326902"
                  style={{ padding:'6px 8px', border:'1px solid var(--sp-border-primary)', borderRadius:'var(--sp-radius-sm)', maxWidth:'160px' }}
                />
                <Button onClick={()=>{ try { loadEvents(); loadReminders(); } catch {} }}>Применить</Button>
              </Space>
            </div>
          )}
        </Card>

        {/* Статистика */}
      <Card className="sp-edge-highlight sp-card-elevated" title={<><BarChartOutlined /> Статистика</>} bodyStyle={{padding:'12px 16px'}}>
          <Row gutter={16}>
            <Col xs={12} sm={8} md={4}>
              <Statistic 
                title="Всего" 
                value={stats.total} 
                prefix={<CalendarOutlined />}
              />
            </Col>
            <Col xs={12} sm={8} md={4}>
              <Statistic 
                title="Ожидают" 
                value={stats.pending} 
                prefix={<ClockCircleOutlined />}
                valueStyle={{ color: 'var(--sp-color-primary)' }}
              />
            </Col>
            <Col xs={12} sm={8} md={4}>
              <Statistic 
                title="Просрочено" 
                value={stats.overdue} 
                prefix={<ExclamationCircleOutlined />}
                valueStyle={{ color: 'var(--sp-color-danger)' }}
              />
            </Col>
            <Col xs={12} sm={8} md={4}>
              <Statistic 
                title="Выполнено" 
                value={stats.completed} 
                prefix={<CheckCircleOutlined />}
                valueStyle={{ color: 'var(--sp-color-success)' }}
              />
            </Col>
            <Col xs={12} sm={8} md={4}>
              <Statistic 
                title="Повторяющиеся" 
                value={stats.recurring} 
                prefix={<BellOutlined />}
                valueStyle={{ color: 'var(--sp-color-info)' }}
              />
            </Col>
          </Row>
        </Card>

        {error && (
          <Alert
            message="Ошибка"
            description={error}
            type="error"
            closable
            onClose={() => setError(null)}
          />
        )}

        {/* Основной контент */}
        <Card className="sp-edge-highlight sp-card-elevated" bodyStyle={{padding:12}}>
          <Tabs activeKey={activeTab} onChange={setActiveTab} items={undefined}>
            {/* Календарная сетка */}
            <TabPane 
              tab={<><CalendarOutlined /> Календарь</>} 
              key="calendar"
            >
              <Spin spinning={loading}>
                <CalendarGrid
                  reminders={reminders}
                  onReminderCreate={handleReminderCreate}
                  onReminderUpdate={handleReminderUpdate}
                  onReminderDelete={handleReminderDelete}
                  loading={loading}
                />
              </Spin>
            </TabPane>

            {/* Список напоминаний */}
            <TabPane 
              tab={<><BellOutlined /> Напоминания</>} 
              key="reminders"
            >
              <Spin spinning={loading}>
                <div className="space-y-4">
                  {/* Просроченные */}
                  {groupedReminders.overdue.length > 0 && (
                    <Card 
                      size="small" 
                      title={
                        <Space>
                          <ExclamationCircleOutlined style={{ color: '#f5222d' }} />
                          <span>Просроченные ({groupedReminders.overdue.length})</span>
                        </Space>
                      }
                    >
                      <List
                        dataSource={groupedReminders.overdue}
                        renderItem={(reminder) => (
                          <List.Item>
                            <List.Item.Meta
                              title={
                                <Space>
                                  <Text strong>{reminder.title}</Text>
                                  <Tag className={getTypeClass(reminder.reminder_type)}>
                                    {reminder.reminder_type}
                                  </Tag>
                                  <Tag className={getPrioClass(reminder.priority)}>
                                    {reminder.priority}
                                  </Tag>
                                </Space>
                              }
                              description={
                                <Space direction="vertical" size="small">
                                  <Text>{reminder.description}</Text>
                                  <Text type="danger">
                                    <ClockCircleOutlined /> {dayjs(reminder.reminder_date).format('DD.MM.YYYY HH:mm')}
                                  </Text>
                                </Space>
                              }
                            />
                          </List.Item>
                        )}
                      />
                    </Card>
                  )}

                  {/* Сегодня */}
                  {groupedReminders.today.length > 0 && (
                    <Card 
                      size="small" 
                      title={
                        <Space>
                          <BellOutlined style={{ color: '#1890ff' }} />
                          <span>Сегодня ({groupedReminders.today.length})</span>
                        </Space>
                      }
                    >
                      <List
                        dataSource={groupedReminders.today}
                        renderItem={(reminder) => (
                          <List.Item>
                            <List.Item.Meta
                              title={
                                <Space>
                                  <Text strong>{reminder.title}</Text>
                                  <Tag className={getTypeClass(reminder.reminder_type)}>
                                    {reminder.reminder_type}
                                  </Tag>
                                  <Tag className={getPrioClass(reminder.priority)}>
                                    {reminder.priority}
                                  </Tag>
                                </Space>
                              }
                              description={
                                <Space direction="vertical" size="small">
                                  <Text>{reminder.description}</Text>
                                  <Text type="secondary">
                                    <ClockCircleOutlined /> {dayjs(reminder.reminder_date).format('HH:mm')}
                                  </Text>
                                </Space>
                              }
                            />
                          </List.Item>
                        )}
                      />
                    </Card>
                  )}

                  {/* Предстоящие */}
                  {groupedReminders.upcoming.length > 0 && (
                    <Card 
                      size="small" 
                      title={
                        <Space>
                          <ClockCircleOutlined style={{ color: '#52c41a' }} />
                          <span>Предстоящие ({groupedReminders.upcoming.length})</span>
                        </Space>
                      }
                    >
                      <List
                        dataSource={groupedReminders.upcoming.slice(0, 10)}
                        renderItem={(reminder) => (
                          <List.Item>
                            <List.Item.Meta
                              title={
                                <Space>
                                  <Text strong>{reminder.title}</Text>
                                  <Tag className={getTypeClass(reminder.reminder_type)}>
                                    {reminder.reminder_type}
                                  </Tag>
                                  <Tag className={getPrioClass(reminder.priority)}>
                                    {reminder.priority}
                                  </Tag>
                                </Space>
                              }
                              description={
                                <Space direction="vertical" size="small">
                                  <Text>{reminder.description}</Text>
                                  <Text type="secondary">
                                    <ClockCircleOutlined /> {dayjs(reminder.reminder_date).format('DD.MM.YYYY HH:mm')}
                                  </Text>
                                </Space>
                              }
                            />
                          </List.Item>
                        )}
                      />
                    </Card>
                  )}

                  {reminders.length === 0 && (
                    <Empty 
                      description="Нет напоминаний"
                      image={Empty.PRESENTED_IMAGE_SIMPLE}
                    />
                  )}
                </div>
              </Spin>
            </TabPane>

            {/* События из сообщений */}
            <TabPane 
              tab={<><InfoCircleOutlined /> События из сообщений</>} 
              key="events"
            >
              <Spin spinning={loading}>
                {events.length === 0 ? (
                  <Empty 
                    description="Нет событий из сообщений"
                    image={Empty.PRESENTED_IMAGE_SIMPLE}
                  />
                ) : (
                  <List
                    dataSource={events}
                    renderItem={(event) => (
                      <List.Item>
                        <List.Item.Meta
                          title={
                            <Space>
                              <Badge status="processing" />
                              <Text strong>{event.keyword}</Text>
                            </Space>
                          }
                          description={
                            <Space direction="vertical" size="small">
                              <Text>{event.text_preview}</Text>
                              <Space>
                                <Text type="secondary">
                                  <CalendarOutlined /> {event.normalized_date ? 
                                    dayjs(event.normalized_date).format('DD.MM.YYYY') : 
                                    'Дата не определена'
                                  }
                                </Text>
                                <Text type="secondary">
                                  <ClockCircleOutlined /> {dayjs(event.created_at).format('DD.MM.YYYY HH:mm')}
                                </Text>
                              </Space>
                            </Space>
                          }
                        />
                      </List.Item>
                    )}
                  />
                )}
              </Spin>
            </TabPane>
          </Tabs>
        </Card>
      </div>
    </div>
  );
};

export default DatesRemindersV2;
